"""Files every command into a dialect and a category, e.g. CreateTexture -> Blitz3D > Textures.

Language Features holds what the language itself has: control flow, functions, loops, types, keywords, math,
strings, time and random numbers. BlitzBasic holds what all three dialects share, Blitz3D what needs a 3D world, BlitzPlus what only BlitzPlus has.
Rules are tried in order, the first match wins. A command nothing matches ends up in "Other", which wiki.py check
rejects, so a new command has to be given a category here.
"""
import re

LANG, BASIC, B3D, PLUS = "Language-Features", "BlitzBasic", "Blitz3D", "BlitzPlus"
# What the sidebar and the pages call a dialect, where it differs from its name.
TITLES = {LANG: "Language Features"}
# Categories whose name has a character that page names cannot have: the pages are called Time-and-Date.
DISPLAY = {"Time and Date": "Time & Date"}


def display(category):
    return DISPLAY.get(category, category)

