def categorize(name, module):
    """Returns (dialect, category) for a lowercase command name from the given suite module."""
    if name in _OVERRIDES:
        return _OVERRIDES[name]
    for rule in _RULES.get(module, []):
        pattern, *target = rule
        if re.search(pattern, name):
            if len(target) == 2:
                return tuple(target)
            return (PLUS if module.startswith("plus") else BASIC), target[0]
    return (BASIC, "Other")
